{
  "id": "error.export_permission_denied",
  "screenState": "ERROR",
  "scenario": "書き出し先フォルダに書き込み権限がない。別の保存先を選ぶ導線を出す。",
  "elements": [
    {
      "id": "errorTitle",
      "component": "ErrorSurface",
      "copyKey": "errors.exportPermissionDenied.title",
      "text": "保存先に書き込めません"
